export const NEWS_ARTICLES: NewsArticle[] = [
  article({
    slug: 'after-rain-roof-leak-check-canberra', title: 'Why does my roof leak only in heavy rain?',
    description: 'Understand intermittent roof leaks, what rain patterns can reveal, and the safe observations that help an inspection trace the source.',
    summary: 'A leak that disappears in light rain still deserves investigation. Learn which observations help explain the pattern.',
    lead: 'A roof leak that appears only in heavy rain can involve a water-entry detail, drainage that cannot clear the incoming water, or several conditions acting together. The weather pattern is a useful clue, but it does not identify the failed component. Start by recording when and where water appears, then have the roof and its drainage assessed together.',
    serviceTitle: 'Roof Leak Repairs', servicePath: '/services/roof-leak-repairs',
    sections: [
      section('rain-pattern', 'What the rain pattern can tell you',
        'Think about the difference between a long, steady shower and a short downpour. Both wet the roof, but they do not send water through its drainage system at the same rate. A problem that shows up only during the heaviest period gives the inspector a reason to examine the route water takes off the roof as well as possible entry points.',
        'A simple way to picture drainage is as a balance between water arriving and water leaving. During a downpour, water may arrive faster than a restricted outlet can clear it, causing the level upstream to rise. Wind can also change where rain reaches a junction. These are possible mechanisms, not diagnoses: the same indoor symptom can arise from different details.',
        'Also record the delay. A drip that starts after rain has eased may reflect water moving through concealed spaces before reaching the room. An intermittent symptom is easy to forget once the ceiling looks dry again, so a dated note helps connect the next event with the earlier one.'),
      section('stain-location', 'Why the ceiling stain is only a starting point',
        'The place where water becomes visible is not necessarily directly beneath the outside opening. Roof layers, framing and other surfaces can affect its path. An inspection therefore needs to connect the interior evidence to plausible exterior details, rather than replacing the nearest visible component and assuming the investigation is finished.',
        'Photograph the whole room first, then the affected patch from a safe position. Include a fixed reference such as a doorway so someone unfamiliar with the house can locate it. Note whether the mark is new, has expanded or has darkened. Keep the earlier photograph instead of replacing it with the latest one.',
        'Mention nearby chimneys, roof junctions or visible gutter overflow if you know about them, but do not climb up to establish their position. Equally, report dampness that occurs without rain. Plumbing moisture and condensation can require a different investigation, and a complete history helps avoid narrowing the assessment too soon.'),
      section('safe-response', 'Protect people before collecting evidence',
        'Keep away from a sagging ceiling or water near electrical fittings. Do not touch a wet light, switch or appliance to find out whether it is working. Move away from the affected area and seek appropriate professional assistance. A photograph is optional; it is never a reason to enter an unsafe space.',
        'Do not go onto the roof during or after the storm to clear a suspected blockage or apply a patch. Ground-level observations and an indoor description are enough to start a conversation. ACT Emergency Services Agency publishes storm guidance; call 000 for an immediate threat to life and ACTSES on 132 500 for storm or flood emergency assistance.',
        'When the immediate situation is stable, retain the time, weather and location notes in one place. You do not need technical vocabulary or a close-up roof photograph. A short, accurate account of the sequence gives the person assessing the roof something they can test against what is actually visible on site.'),
      section('investigation', 'What a useful leak investigation should resolve',
        'The assessment should explain which details were checked and why they relate to the reported symptom. Depending on the roof, that may involve coverings, junctions, valleys, gutters and accessible internal evidence. Ask how the proposed repair addresses the suspected water route, and which parts of that route remain concealed or unconfirmed.',
        'A dry-weather visit can still reveal defects, but the absence of a drip during the appointment is not proof that the intermittent problem has disappeared. Share earlier observations and any previous repair records. If further investigation is proposed, clarify its purpose and scope before treating it as an additional repair.',
        'After work, keep the repair description with your original notes. If the symptom returns, record the weather and whether it is in the same location. This makes the follow-up specific: what changed, what was repaired and what is still happening. Repeated patches without that connection can leave the underlying question unanswered.'),
    ], related: ['gutters-overflowing-heavy-rain-canberra', 'roof-leak-vs-condensation-canberra', 'when-to-arrange-roof-inspection-canberra', 'chimney-flashing-water-entry-signs'], sources: [storm, steel],
  }),
  article({
    slug: 'cracked-slipped-missing-roof-tiles-canberra', title: 'Can one or two damaged roof tiles be replaced?',
    description: 'Learn when a small tile repair may be suitable, why tile profile matters, and what surrounding defects an inspection should consider.',
    summary: 'A small number of damaged tiles does not automatically mean a whole new roof. The fit and surrounding condition matter.',
    lead: 'One or two damaged roof tiles may be suitable for a local repair when the surrounding roof is sound and a compatible replacement is available. The number visible from the ground is only the starting point. An inspection needs to establish what is damaged, why a tile has moved, and whether the adjoining roof details also need attention.',
    serviceTitle: 'Tile Roof Repairs', servicePath: '/services/tile-roof-repairs',
    sections: [
      section('damage', 'Separate a damaged tile from a wider roof problem',
        'A crack, a missing piece and a tile that has slipped out of line are different observations. Each gives the inspector a different question to answer. Record the position and appearance in plain language rather than treating them as interchangeable faults. A photograph from the ground can show the general area even when it cannot show the complete defect.',
        'A displaced tile also raises the question of why it moved. The assessment may need to consider how it sits with neighbouring tiles and the condition of its support and fixing arrangements. Simply moving it back into line does not explain whether the cause has been addressed. Ask for that distinction in the proposed work.',
        'Inside the house, note any fresh stain or drip and when it began. A visible tile defect and an indoor stain may be connected, but their proximity alone does not prove the route. If there is no indoor symptom, describe that accurately too; a concern does not have to be leaking visibly before it is worth checking.'),
      section('matching', 'A replacement needs to fit, not just match the colour',
        'A tiled roof is an assembly of overlapping units, not a single continuous sheet. A replacement needs to sit correctly with the units beside it and above it so those relationships are maintained. Tiles of a similar colour or overall size can have different profiles. That is why compatibility is a fitting question before it is an appearance question.',
        'If you have spare tiles stored safely at ground level, mention them and provide a photograph of any markings without moving heavy stacks. Existing records from the roof installation or an earlier repair can also help. Do not remove a tile from the roof yourself to obtain a sample or read its underside.',
        'An exact visual match may be difficult on a weathered roof. Discuss appearance separately from fit and performance so that you know what the finished repair is expected to look like. If a compatible product cannot be sourced, ask what alternatives are being considered and how much additional roof area they would affect.'),
      section('scope', 'Understand what the local repair includes',
        'A useful repair description identifies the affected roof area and the work proposed there. It should make clear whether the price covers only individual tile replacement or connected work at a ridge, valley or flashing. That distinction is especially helpful when one quotation appears much larger than another for the same visible defect.',
        'For example, a quote to replace two tiles and a quote that also repairs an adjoining junction are not pricing the same task. Ask for the evidence behind the extra work. There may be a sound reason for it, but a broad description such as “repair roof” makes it hard to see which problem each item addresses.',
        'Monier’s maintenance guidance distinguishes broken tiles from ridge bedding and drainage concerns. That is a useful reminder to assess the components separately. A small visible defect does not establish that the whole roof is failing, and a small replacement does not establish that every neighbouring detail is in good condition.'),
      section('follow-up', 'Keep the repair proportionate and the record useful',
        'Do not walk on the roof to count damaged tiles or test whether one is loose. An apparently small job can still require planned access and work at height. The cost of those arrangements is separate from the price of the tile itself, which helps explain why a two-tile job cannot be priced from material cost alone.',
        'Before approving work, clarify how additional defects discovered during access will be communicated. A sensible record separates the agreed repair from anything awaiting a further decision. If the concern followed a storm, include the date and what changed; the timing is useful context but is not proof of the cause of every defect.',
        'Keep the location, replacement information and completion photographs where available. If a leak prompted the repair, continue to note any new moisture after rain and share it with the person responsible for the assessment. That follow-up helps distinguish the repaired tile issue from a separate water-entry path that may need investigation.'),
    ], related: ['rebedding-vs-repointing-canberra-roofs', 'roof-repair-vs-restoration-vs-replacement-canberra', 'after-rain-roof-leak-check-canberra'], sources: [tiles, storm],
  }),
  article({
    slug: 'chimney-flashing-water-entry-signs', title: 'What can cause water stains near a chimney?',
    description: 'Understand the chimney-to-roof junction, what flashing does, and why an indoor stain needs investigation before a repair is chosen.',
    summary: 'The stain may point toward a chimney junction, but it cannot tell you which part has failed.',
    lead: 'A water stain near a chimney may involve the roof-to-chimney flashing, adjoining roofing or another part of the chimney assembly. Flashing helps direct water around the junction, but an indoor mark does not identify a flashing defect by itself. The useful question is how water reaches that location and which component needs repair.',
    serviceTitle: 'Chimney Flashing Repairs', servicePath: '/services/chimney-flashing-repairs',
    sections: [
      section('junction', 'Why this junction needs a closer look',
        'Where a chimney passes through a sloping roof, the covering must meet a raised object rather than continue as an uninterrupted surface. Water approaching that area needs a route around it and back onto the roof. Flashing is part of that arrangement, so its relationship with the adjoining materials matters as much as its visible appearance.',
        'The LYSAGHT maintenance manual includes flashings and sealants among the details that need checking on metal roofing. This supports looking at the complete junction rather than one conspicuous patch. The precise construction differs between roof systems, so a generic diagram or a photograph of another house cannot establish the repair required on yours.',
        'From the ground, you might notice lifted-looking material, gaps or old patching. Report those as observations. Concealed overlaps and connections cannot be assessed reliably from that view, and a piece that looks weathered is not automatically the active entry point. Conversely, a tidy-looking surface may conceal a detail that needs closer inspection.'),
      section('pattern', 'Describe where and when the stain changes',
        'Start with the indoor location: ceiling beside the chimney breast, wall surface, or another nearby area. Include a wider photograph so the room and orientation are clear, followed by a closer image if it is safe. Record whether the mark is fresh or an older stain whose edges have recently changed.',
        'The weather history can help focus the inspection. Note whether the stain appears during steady rain, after prolonged rain or only when wind accompanies it. If you know the approximate wind direction, include it without assuming that it proves an opening on that side. Several roof details may be exposed in the same weather.',
        'Mention any dampness during dry weather and any earlier work at the chimney or nearby roof. Old invoices and photographs are helpful because they show what was actually changed. “It was repaired before” provides less information than a record saying which junction or component was worked on and when the symptom returned.'),
      section('diagnosis', 'Ask how the proposed repair follows the evidence',
        'An assessment should connect the observed defect with a plausible water path. Ask which part of the junction was visible, what was found and whether adjoining tiles or sheets were checked. If an area could not be reached safely or remained concealed, that limitation should stay visible in the explanation rather than becoming an assumed diagnosis.',
        'A quotation for surface sealing is different from one that renews part of the flashing arrangement. Neither description is enough on its own to judge suitability. The explanation should say why that approach fits the observed defect, what preparation is included and whether other parts of the junction remain outside the work.',
        'Avoid repeatedly adding sealant without understanding the detail underneath. A repair should restore the intended water route, and the contractor needs to assess the materials and connections involved. This is not a task to investigate by leaning over a chimney, lifting roof materials or testing patches from an unsafe position.'),
      section('boundaries', 'Keep roofing work and chimney work clearly defined',
        'A roof junction repair does not automatically include chimney masonry, internal flue work or other chimney components. If the assessment points beyond the roofing detail, ask which further specialist assessment is needed. Clear boundaries help prevent a roof repair being approved on the assumption that it resolves every possible source of moisture around the chimney.',
        'Before work, identify the roof area, the component to be repaired and any exclusions in the written scope. Ask what photographs or written findings will be provided, especially if you cannot attend. These records help explain both the completed work and any separate issue that still needs a decision.',
        'Afterwards, use the original indoor photographs as a reference if the mark changes again. An old stain remaining visible is different from fresh dampness spreading after rain. Report the timing and change rather than trying to judge the repair from the stain colour alone, and keep away from any unsafe ceiling or electrical area.'),
    ], related: ['after-rain-roof-leak-check-canberra', 'when-to-arrange-roof-inspection-canberra', 'roof-repair-cost-canberra'], sources: [steel],
  }),
  article({
    slug: 'rebedding-vs-repointing-canberra-roofs', title: 'Does cracked ridge mortar need rebedding or repointing?',
    description: 'A plain-English explanation of roof bedding and pointing, why cracks need assessment, and how to understand a proposed ridge repair.',
    summary: 'The supporting bed and the exposed pointing do different jobs. A crack alone does not tell you which needs renewal.',
    lead: 'Rebedding renews the mortar bed beneath ridge or hip caps; repointing renews the exposed pointing finish over the bedding. Whether cracked ridge mortar needs one or both depends on the condition of the underlying bed and caps. A photograph can flag a concern, but it cannot reliably establish whether the support underneath is sound.',
    serviceTitle: 'Rebedding & Repointing', servicePath: '/services/rebedding-repointing',
    sections: [
      section('two-layers', 'Two parts of the same detail',
        'Ridge caps cover the meeting line at the top of a tiled roof, while hip caps follow the sloping external corners. On a bedded system, mortar forms the bed beneath those caps. The exposed pointing is a separate part of the detail. The terms describe different work, even though a quotation may discuss them together.',
        'Monier’s ridge and hip capping drawings label mortar bedding and flexible pointing separately. They help explain the arrangement of the components, rather than prescribe a repair for an existing roof. Selleys’ Point Works guidance also requires contact with the roof and ridge tiles. The visible finish therefore needs to be considered as part of a connected detail.',
        'When discussing a repair, ask which material is cracked and what evidence supports that conclusion. “Ridge repair” is a useful category but an incomplete work description. You should be able to understand whether caps are being lifted and rebedded, whether existing bedding is being retained, and where new pointing will be applied.'),
      section('assessment', 'What a crack can and cannot establish',
        'A fine surface crack, a visible gap and a displaced cap are different signs. Record their location from a safe ground-level position, including whether one short area or several roof lines appear affected. Do not touch or push caps to test their stability. That assessment belongs with the person planning safe access to the roof.',
        'Repointing may be considered where the supporting bed remains suitable and the problem is in the exposed finish. If the bedding or cap arrangement needs renewal, covering it with a new finish does not remove that underlying issue. Ask how the assessment distinguishes those conditions rather than accepting either treatment as a default package.',
        'A crack also does not establish the source of an indoor leak. If ceiling moisture prompted the enquiry, describe its timing separately. The inspection may need to follow other details nearby as well. Keeping the visible ridge concern and the indoor symptom distinct allows the explanation to show whether and how they are connected.'),
      section('extent', 'Why the length and preparation change the scope',
        'A proposal for a short ridge section differs from a proposal for every ridge and hip. Ask for the roof lines to be identified in a photograph, sketch or written description. An approximate length is useful only when everyone understands which lines it includes and whether any areas are excluded or awaiting closer assessment.',
        'Preparation is another meaningful difference between quotes. The scope should explain how unsound material will be dealt with and which base is being retained. Avoid comparing only the name of the pointing product or the final colour; neither tells you what happens beneath the visible finish or how much work is included.',
        'The selected product also has application and curing conditions. Weather can affect when that work can be carried out, and the requirements vary by material. Discuss scheduling with the contractor instead of treating a dry-looking roof on the morning of the appointment as proof that all conditions are suitable.'),
      section('decision', 'Make the repair decision understandable',
        'Before approving the work, ask for three things in ordinary language: what was found, which ridge areas need attention and what treatment is proposed for each. If some areas need rebedding and others only repointing, the description should preserve that distinction. A single broad label can otherwise hide a useful difference in scope.',
        'Ask how broken adjacent tiles or other defects found during access will be handled. They may be connected to the work area, but they are not automatically included because the quote mentions ridges. Clarifying the approval process for additional work helps keep a targeted repair from becoming an undefined programme of roof maintenance.',
        'Completion photographs and a written record can show the locations worked on and any follow-up recommended. Keep them with the original observations. The purpose is to understand what has changed and what remains, rather than to judge concealed bedding solely from the appearance of the new pointing.'),
    ], related: ['roof-repointing-cost-canberra', 'cracked-slipped-missing-roof-tiles-canberra', 'roof-repair-vs-restoration-vs-replacement-canberra'], sources: [pointing, pointingConditions, tiles],
  }),
  article({
    slug: 'when-to-arrange-roof-inspection-canberra', title: 'What should a roof inspection check after a leak or storm?',
    description: 'What a roof inspection can establish, which roof and drainage details matter, and how findings become a clear repair scope.',
    summary: 'A useful inspection connects the symptom, the observed roof condition and the proposed work, while explaining its limits.',
    lead: 'A roof inspection after a leak or storm should connect your observations with the condition of the roof covering, junctions and drainage. It should also explain what could not be checked. The useful outcome is an account of what was found and what needs to happen next, rather than a list of roof components without a connection to the problem.',
    serviceTitle: 'Roof Inspections', servicePath: '/services/roof-inspections',
    sections: [
      section('purpose-access', 'Agree the purpose and access before the visit',
        'A recurring bedroom leak, a displaced tile after wind and a general maintenance review begin with different questions. State the reason for the inspection and share the symptom history. If it concerns a property purchase or sale, explain that context and confirm whether the offered inspection meets the particular purpose you have in mind.',
        'Discuss access before the appointment, including roof height, locked gates and occupied rooms. Roof-space access should be agreed where relevant; its availability does not mean every concealed area can be inspected. The appointment needs to account for safe working conditions, and weather or physical restrictions may limit what can be seen on the day.',
        'Confirm any inspection fee and the findings to be supplied, such as photographs and a written explanation. These are separate questions from the cost of later repairs. Knowing the deliverable in advance helps you use the visit well, especially when an owner or property manager will review the findings remotely.'),
      section('roof-system', 'Follow the covering, junctions and drainage together',
        'The checks should reflect the actual roof material. For tiles, relevant observations can include broken or displaced units and ridge-cap details. For metal roofing, the assessment may look at sheets, laps, fasteners and visible corrosion. The important point is to relate the observed condition to the concern, rather than assume every roof needs the same treatment.',
        'Junctions and openings deserve attention because the covering changes direction or meets another component there. Chimneys, walls, valleys and penetrations can be relevant, depending on the reported location. LYSAGHT’s maintenance manual includes flashings and drainage among its inspection topics, reinforcing the need to look beyond the main roof surface.',
        'The water route continues through gutters, outlets and downpipes. If overflow accompanied the leak, include it in the record. Accessible interior evidence can help connect these exterior observations with the room below, but a ceiling stain alone cannot identify one failed component. The explanation should distinguish an observed defect from an inferred water path.'),
      section('findings', 'Turn findings into a repair scope',
        'Useful findings identify a location, describe the condition and explain the proposed response. A photograph with a room or roof-area reference is easier to act on than an unlabelled close-up. Ask which items relate to active water entry, which are maintenance concerns and which require further investigation before a repair decision can be made.',
        'A local tile replacement, work at a chimney junction and a wider roof renovation are different proposals. If broader work is recommended, ask what it resolves beyond the immediate symptom and what a smaller repair would leave unresolved. That creates a clear comparison without assuming the smallest or largest option must be the right one.',
        'Limitations belong in the findings too. An inaccessible section should be recorded as uninspected, not silently treated as sound. Likewise, a dry-weather visit may identify a suspected cause without reproducing an intermittent leak. Ask what evidence supports the conclusion and how any remaining uncertainty affects the proposed next step.'),
      section('next-step', 'Prepare for a useful decision after the inspection',
        'Bring together the room location, weather history, safe photographs and records of earlier work. You do not need to diagnose the problem before arranging the visit. A concise account of what changed gives the inspector a starting point and makes it easier to check whether the eventual recommendation answers your original concern.',
        'Inspection and repair are not automatically the same appointment. Materials, weather, the agreed scope and authorisation can affect whether work is possible during the visit. Clarify this before booking, particularly if someone else is providing access. An inspection appointment should not be mistaken for approval of an undefined repair.',
        'When the quotation arrives, compare it with the findings. Confirm the named areas, proposed materials, access arrangements, exclusions and any further investigation. Keep the inspection record even if repairs happen later; it provides a dated baseline for understanding new symptoms or discussing a change in the scope.'),
    ], related: ['after-rain-roof-leak-check-canberra', 'roof-repair-cost-canberra', 'roof-repair-vs-restoration-vs-replacement-canberra'], sources: [steel, storm],
  }),
  article({
    slug: 'roof-repair-cost-canberra', title: 'Why do roof repair quotes differ?',
    description: 'Compare roof repair quotes by diagnosis, work area, materials, access and exclusions instead of relying on a misleading average price.',
    summary: 'Two quotes can describe very different jobs. Learn how to make the scope comparable before judging the total.',
    lead: 'Roof repair quotes differ because the work, access and assumptions can differ, even when both contractors have seen the same ceiling stain. A useful comparison starts with the defect being addressed and the roof area included. There is no reliable price for “a leak” until the proposed investigation and repair are defined.',
    serviceTitle: 'Roof Leak Repairs', servicePath: '/services/roof-leak-repairs',
    sections: [
      section('same-job', 'Check whether the quotes describe the same job',
        'One proposal might replace a damaged tile while another includes work at an adjoining junction. A third may be an inspection price rather than a repair price. Put the descriptions beside one another and identify what each actually buys. A lower total is meaningful only after those differences are visible.',
        'Start with the location and finding. “Repair leaking roof” does not tell you which component will be changed or why. Ask for the affected area, the observed defect and the proposed response in plain language. If the cause remains uncertain, distinguish the cost of investigating it from a price based on an established repair scope.',
        'Previous work matters as context, too. If a leak has returned after patching, a new quotation should explain what it proposes to investigate or change this time. Otherwise, two similarly priced visits may repeat the same limited task without answering why the symptom persists.'),
      section('cost-drivers', 'Separate materials from access and preparation',
        'The price of a replacement tile or a container of pointing is not the price of a completed repair. The job may also involve obtaining a suitable material, reaching the area safely, preparing the existing detail and handling waste. Ask which of these activities are included instead of assuming they are the same across quotations.',
        'Roof height, pitch and restricted access can change the work arrangements. A defect close to a roof edge on one property may require a different approach on another. This is why a neighbour’s total, or an online price attached to a short description, may not be a useful benchmark for your own roof.',
        'Preparation can explain another difference. A proposal that renews an unsound base is different from one that treats only a surface. Monier’s capping drawings distinguish bedding from pointing, while Selleys’ product guidance describes the contact required with adjoining tiles. Ask what the contractor proposes to retain, remove and prepare for the selected material.'),
      section('unknowns', 'Make exclusions and uncertain items visible',
        'An exclusion is useful information when it tells you where the job stops. Check whether adjacent components, internal ceiling repairs, further investigation or inaccessible areas are outside the price. Do not assume an item is covered because it is near the repair or mentioned in an inspection photograph.',
        'Ask how additional work will be proposed if access reveals a hidden defect. The useful answer describes how the new finding, scope and price will be communicated for a decision. An allowance or provisional item should be understandable enough that you can see what event might change the final amount.',
        'Also clarify tax treatment, waste removal, inspection charges and any separate attendance fee in the actual quote. Do not fill gaps using a general website description. A written proposal for your property is the place to establish what is included and how payment relates to the agreed stages of work.'),
      section('comparison', 'Choose with evidence, not just a headline total',
        'A simple comparison can use four columns on a page: roof area, proposed work, exclusions and unresolved questions. Copy the wording from each quotation before asking for clarification. That makes it easier to see whether the difference is a material choice, a larger work area or a different understanding of the problem.',
        'Ask what completion information will be supplied and what follow-up is appropriate if the original symptom returns. This is particularly useful for an intermittent leak that may not occur on the day of repair. Photographs and a clear record of work help make a later conversation about evidence rather than recollection.',
        'The aim is not to turn every small repair into a complex tender. It is to remove the few uncertainties that could change your decision. Once the scope is clear, you can weigh the total against the work proposed, the explanation given and the practical arrangements for your property.'),
    ], related: ['roof-repointing-cost-canberra', 'when-to-arrange-roof-inspection-canberra', 'roof-repair-vs-restoration-vs-replacement-canberra'], sources: [pointing, pointingConditions],
  }),
  article({
    slug: 'roof-repointing-cost-canberra', title: 'What should a roof repointing quote include?',
    description: 'Understand ridge lengths, bedding condition, preparation and exclusions so you can compare repointing quotes for the actual work proposed.',
    summary: 'The final pointing finish is only part of the job. A useful quote explains the roof lines, the base and the preparation.',
    lead: 'A roof repointing quote should identify the ridge and hip areas included, the condition of the existing bedding, the preparation proposed and the pointing material to be used. It should also distinguish any rebedding from repointing. Without those details, similar-looking prices may cover substantially different work.',
    serviceTitle: 'Rebedding & Repointing', servicePath: '/services/rebedding-repointing',
    sections: [
      section('roof-lines', 'Identify the roof lines being priced',
        'Start with a marked photograph, sketch or clear written description of the ridges and hips. “Repoint roof” does not show whether the proposal covers one damaged section, all visible lines or areas that were not inspected. You should be able to connect the price to an identifiable part of the building.',
        'A length measurement can be useful, but only with that location information. Two quotations using similar lengths may still include different roof lines or different work at intersections. Ask whether small adjoining sections are included and whether the extent is confirmed or subject to closer access.',
        'If one contractor proposes the whole roof and another proposes a local repair, ask for the condition-based reason behind each approach. The larger scope may address more widespread deterioration, or it may simply reflect a different assumption. The explanation should show what a targeted repair would leave in place.'),
      section('base-preparation', 'Make bedding and preparation explicit',
        'Pointing and bedding are separate parts of the ridge detail. The quote should say whether the existing bed is suitable to retain or whether caps and bedding need further work. A surface finish cannot by itself demonstrate the condition of the underlying support, so ask what was observed before the treatment was selected.',
        'Preparation deserves its own explanation. Ask how loose or unsuitable material will be dealt with and how the retained surface will be prepared for the selected product. Monier’s drawings show the separate bedding and pointing components; Selleys’ guidance explains product-specific contact and application conditions. Neither should be treated as a universal repair specification for every roof.',
        'Where rebedding is needed only in selected areas, those locations should be named separately. That makes it possible to compare a combined quote with one that prices repointing alone. It also avoids assuming that every cap will be lifted simply because the quotation uses both terms in its heading.'),
      section('conditions', 'Check materials, access and weather assumptions',
        'Ask which pointing product is proposed and whether colour selection is part of the agreement. Product compatibility and preparation matter more than choosing a colour from a photograph. If an existing finish will remain beside the repair, clarify what visual difference to expect rather than assuming an invisible match.',
        'Weather affects the use of pointing products. Application and curing requirements belong to the selected material, and cold or wet conditions can affect scheduling. A contractor should plan around those requirements. A promised date needs room for unsuitable conditions rather than encouraging work simply because an appointment has been booked.',
        'Access arrangements can also influence the quotation independently of ridge length. Ask whether the stated price includes the planned means of reaching and working on the roof, along with preparation and waste removal. A rate per metre without those assumptions can conceal more than it clarifies.'),
      section('completion', 'Know what remains outside the ridge repair',
        'Broken field tiles, valley defects and flashing work are not automatically included in a repointing quote. If the inspection identifies them, ask whether they are separate items or part of the proposed scope. If a leak prompted the enquiry, the findings should explain why ridge work is relevant to that leak.',
        'Clarify how additional defects discovered during preparation will be documented and approved. Ask for exclusions and any provisional work to be stated plainly, along with tax treatment and the completion information to be provided. These details let you compare the actual agreement rather than a verbal summary.',
        'Keep the quote and any completion photographs with your roof records. They should help you identify which lines were treated and where bedding was renewed. If a later concern arises elsewhere, that record prevents a local repair being remembered as whole-roof work and makes the next assessment more precise.'),
    ], related: ['rebedding-vs-repointing-canberra-roofs', 'roof-repair-cost-canberra', 'when-to-arrange-roof-inspection-canberra'], sources: [pointing, pointingConditions],
  }),
  article({
    slug: 'roof-cleaning-methods-canberra', title: 'How should moss and dirt be cleaned from a roof?',
    description: 'Why roof material and condition should guide cleaning, what to ask about treatment and runoff, and when repairs need to come first.',
    summary: 'Tile and coated metal roofs need material-specific care. Appearance alone cannot determine a suitable cleaning method.',
    lead: 'Roof cleaning should begin with the material, its condition and the type of build-up, rather than a standard pressure or chemical treatment. Concrete tile, terracotta and coated steel are not interchangeable surfaces. A sound cleaning plan explains how the chosen method suits the roof and how drainage, runoff and existing defects will be managed.',
    serviceTitle: 'Roof Cleaning', servicePath: '/services/roof-cleaning',
    sections: [
      section('condition', 'Decide what needs cleaning and what needs repair',
        'A dark patch may be dirt, biological growth, staining or a change in the finish. Its appearance from the ground does not identify the material or establish the treatment. Describe the visible change and where it occurs, then ask how the roof will be assessed before a method is chosen.',
        'Cleaning is also different from repairing a water-entry defect. If there are damaged tiles, loose ridge details or a suspected leak, discuss those concerns before agreeing to cosmetic work. A roof can look cleaner while the original defect remains, so the proposed outcome should distinguish appearance from repair.',
        'Monier notes that respraying is an aesthetic treatment rather than a roof repair. That is a useful boundary when reviewing a cleaning or coating package. Ask which actual defects the work addresses and which require a separate decision, particularly if stopping a leak is your main reason for enquiring.'),
      section('materials', 'Match the method to the roofing material',
        'For coated steel, COLORBOND’s published care guidance recommends gentle, non-abrasive cleaning where ordinary rinsing does not remove dirt. It does not justify treating every roof with the same aggressive process. The relevant manufacturer instructions should guide the choice, including the existing coating and any earlier repairs.',
        'Tiles also differ in material, profile and surface finish. Ask how these have been identified and what guidance supports the proposed method. A description such as “soft wash” or “pressure clean” is not enough to judge suitability without understanding the treatment, condition of the roof and precautions involved.',
        'If moss or other growth is the main concern, discuss whether the proposed product is suitable for the identified material and how its instructions will be followed. Do not apply a household chemical mixture or copy a method from an unrelated roof. The purpose of these questions is to assess the plan, not to turn roof cleaning into a DIY task.'),
      section('water-route', 'Include gutters, runoff and nearby areas in the plan',
        'Removing material from the roof changes where that material goes. Ask how debris and wash water will be managed so that the cleaning process does not simply transfer build-up into gutters or outlets. Drainage should be considered as part of the work area rather than left as an assumption at the end.',
        'Tell the contractor about rainwater collection and any connections you know about. The handling of runoff needs to be agreed for the particular system and treatment. Also mention nearby planted areas, outdoor belongings and access restrictions so the plan can address the property rather than only the roof surface.',
        'Ask what preparation and clean-up are included in the price. A clear scope identifies the roof area, treatment and affected surroundings, together with exclusions. This makes it easier to compare two proposals that may use similar cleaning labels while including different amounts of work.'),
      section('expectations', 'Set a useful maintenance goal',
        'A cleaning result should be judged against an agreed purpose. Removing loose build-up, improving appearance and preparing a surface for further work are different goals. Ask what changes are reasonably expected and whether some staining or weathered colour may remain. Avoid treating a uniform colour as proof that every roof component is sound.',
        'Future maintenance should respond to the roof and its surroundings. Note where build-up returns and whether overhanging vegetation or sheltered areas are involved. That record can guide a later review without assuming that every roof needs the same fixed cleaning interval or repeated treatment.',
        'Keep observations to safe ground-level positions. Roof surfaces and access arrangements require professional planning, especially when water or growth is present. If the roof also leaks or a gutter overflows, retain those as separate concerns until the findings explain whether the cleaning work addresses them.'),
    ], related: ['gutters-overflowing-heavy-rain-canberra', 'roof-repair-vs-restoration-vs-replacement-canberra', 'cracked-slipped-missing-roof-tiles-canberra'], sources: [cleaning, tiles, steel],
  }),
  article({
    slug: 'gutters-overflowing-heavy-rain-canberra', title: 'Why do gutters overflow in heavy rain?',
    description: 'Learn how to distinguish a possible blockage from a drainage defect, what overflow patterns mean, and when cleaning may not be enough.',
    summary: 'Leaves are one possibility, but overflow can involve outlets, downpipes or the drainage arrangement itself.',
    lead: 'Overflowing gutters can result from a blockage, a damaged drainage detail or a system that cannot carry the water arriving during heavy rain. Cleaning may resolve accumulated debris, but it will not correct every defect. The location and timing of the overflow help determine what needs checking next.',
    serviceTitle: 'Gutter & Downpipe Cleaning and Maintenance', servicePath: '/services/gutter-downpipe-maintenance',
    sections: [
      section('pattern', 'Watch the pattern from a safe position',
        'Note where water escapes: one corner, a joint, a long section of gutter or the area beside a downpipe. Describe whether it spills only during the heaviest rain or continues through a lighter shower. These details are more useful than a general report that the gutters are “not working”.',
        'Photographs or a short video from indoors or a sheltered ground-level position can preserve the pattern. Do not stand beneath a damaged edge or use a ladder in the rain to obtain a closer view. If the same area affects a ceiling or wall inside, record that location separately.',
        'Mention recent cleaning, repairs or changes around the roof if known. A problem that continues after debris removal raises a different question from one that first appears when leaves visibly accumulate. The history helps the inspection focus on what remains unresolved without assuming the earlier work caused the problem.'),
      section('drainage', 'Follow the route beyond the gutter',
        'The gutter is one part of a route that includes outlets and downpipes. Debris near an outlet can affect drainage even where the rest of the gutter looks relatively clear from below. An inspection should establish which parts were checked rather than infer that a clean-looking front edge means the route is open.',
        'LYSAGHT’s maintenance guidance treats the roof and rainwater system as connected components. For a homeowner, the practical question is whether water can leave the affected area through the intended path. Ask where any obstruction was found and whether the downstream route needs further assessment.',
        'Location helps separate possible mechanisms. Water escaping at a joint may involve that connection, while a rising water level upstream of an outlet may point toward restricted flow. A gutter can also retain water where its arrangement no longer drains as intended. These patterns focus the assessment, but none proves the cause from a ground-level view alone.'),
      section('clean-or-repair', 'Understand the boundary between cleaning and repair',
        'Cleaning removes accumulated material within the agreed area. Repair changes a defective component or connection. A quote should make clear which task is proposed and whether it includes checking the result. If defects are discovered during cleaning, ask for them to be recorded so you can decide on a separate repair scope.',
        'For example, an outlet cleared of debris and a leaking joint beside it can require two different responses. Completing the cleaning does not automatically include renewing the joint. Naming both findings avoids the impression that the maintenance failed simply because a separate defect remains.',
        'Where overflow persists despite a clear route, further assessment may be needed to understand the layout and the water arriving from the roof. A photograph taken in heavy rain cannot settle that question alone. Ask what evidence is needed before approving a change to the drainage system.'),
      section('record', 'Use the next rainfall as an observation, not a roof test',
        'After maintenance or repair, retain the description of what was completed and observe the area safely when rain returns. Note whether the overflow has stopped, moved or reduced. This gives the person assessing the system a specific comparison with the earlier pattern.',
        'Do not climb up to run water through the gutter yourself or attempt to clear a downpipe from an unsafe position. If water is entering the building or the roof edge appears damaged, describe the immediate concern when seeking assistance. Safety takes priority over collecting a perfect video of the overflow.',
        'Longer-term maintenance should account for the way debris accumulates at your property. Keep a record of recurring trouble spots rather than relying only on a calendar reminder. A clean gutter is useful, but the broader aim is a functioning drainage route with known defects addressed and unresolved questions clearly identified.'),
    ], related: ['after-rain-roof-leak-check-canberra', 'roof-cleaning-methods-canberra', 'roof-repair-cost-canberra'], sources: [steel, storm],
  }),
  article({
    slug: 'roof-leak-vs-condensation-canberra', title: 'Why is the ceiling damp when it has not rained?',
    description: 'Understand roof leaks, condensation and other moisture possibilities, and record the patterns that help a professional investigation.',
    summary: 'Winter dampness can have more than one cause. Weather, room use and the moisture pattern help frame the right questions.',
    lead: 'Ceiling dampness without recent rain can involve condensation, plumbing moisture or water remaining from an earlier event. It should not automatically be labelled a roof leak. The pattern over time matters: record the weather, affected room and when moisture appears so the investigation can consider more than one possible source.',
    serviceTitle: 'Roof Inspections', servicePath: '/services/roof-inspections',
    sections: [
      section('condensation', 'How condensation differs from rain entering a roof',
        'Condensation forms when moist air meets conditions cold enough for water vapour to become liquid. Australian Government Your Home guidance explains this relationship between moisture, surface temperature and ventilation. It is a different mechanism from rain passing through an outside defect, although the resulting dampness can look similar indoors.',
        'The temperature at which water begins to condense is the dew point. A surface can reach it even when the room feels comfortably warm. This explains why a cold window or ceiling area may collect moisture without rain entering from outside. Condensation can also occur within a building assembly, where the first visible sign does not show the full moisture path.',
        'More than one issue may be present. A home can have an exterior roof concern and conditions that allow condensation elsewhere. Keep observations tied to specific rooms and times, so that apparently similar marks are not assumed to share a single source.'),
      section('moisture-diary', 'Record timing, weather and room use together',
        'Write down when you first notice moisture and whether it changes during the day. Include recent rainfall, cold mornings and activities such as showering, cooking or drying washing indoors where relevant. These are clues for an assessment, not a way to assign blame to occupants or diagnose the building remotely.',
        'Record the position and shape of the affected area, along with any window condensation or other nearby dampness. A whole-room photograph and dated close-up can help compare changes. Do not enter the roof space or disturb wet materials to obtain more evidence; the accessible indoor observations are sufficient to begin.',
        'If the patch grows after rain, keep that information even when moisture also appears on dry days. If it seems related to a fixture or plumbing use, mention that too. A mixed pattern is worth reporting accurately instead of simplifying it to fit the first explanation suggested.'),
      section('assessment', 'Investigate the moisture source before choosing a fix',
        'An assessment may need to consider the roof, plumbing and the way moisture is removed from the home. Ask which possibilities were examined, what evidence supports the conclusion and whether another trade or building specialist is needed. A roof-only visit may have a useful but limited scope.',
        'Ventilation, insulation and air movement can interact, so avoid assuming that one added vent or one insulation change will resolve every case. The right response depends on the building and the identified moisture path. Any recommendation should explain what it is intended to change and how that relates to the observations.',
        'A dry surface on the day of inspection does not erase the history. Share the earlier photographs and dates, and ask how inaccessible or concealed areas affect the conclusion. Where the source remains uncertain, a defined next investigation is more useful than presenting an untested explanation as a confirmed diagnosis.'),
      section('response', 'Keep the response focused on the cause',
        'Repainting a stain changes its appearance, but it does not establish that the moisture source has been addressed. Discuss the cause and any affected materials before arranging a cosmetic finish. Keep the earlier record so that new dampness can be distinguished from an old mark that remains visible.',
        'Do not touch water near electrical fittings or remain beneath a ceiling that appears unsafe. Move away and seek appropriate assistance. The absence of rain does not make a wet ceiling harmless, and you do not need to establish whether the roof is responsible before describing an immediate safety concern.',
        'After any agreed work, continue the same short record of weather, room use and moisture location. A change in the pattern can help assess the result or focus further investigation. The goal is to explain and control the source, rather than repeatedly treating the visible stain as the whole problem.'),
    ], related: ['after-rain-roof-leak-check-canberra', 'when-to-arrange-roof-inspection-canberra', 'roof-leak-information-for-tenants-canberra'], sources: [condensation],
  }),
  article({
    slug: 'roof-repair-vs-restoration-vs-replacement-canberra', title: 'Can the roof be repaired, or does it need wider work?',
    description: 'Compare local roof repair, renovation and replacement by the condition, extent of defects and the problems each option would leave unresolved.',
    summary: 'A leak or a tired appearance does not settle the decision. Start with the condition and extent of the defects.',
    lead: 'The choice between a local repair, wider renovation and replacement should follow the roof’s condition and the extent of its defects. One leak does not automatically justify a new roof, and a fresh finish does not resolve every water-entry problem. Ask what each option addresses, what it retains and what it leaves unresolved.',
    serviceTitle: 'Roof Renovation', servicePath: '/services/roof-renovation',
    sections: [
      section('local-repair', 'When a local repair is the question to explore',
        'A local repair focuses on a defined component or area, such as damaged tiles or a particular junction. It is worth considering when the assessment identifies a limited defect and finds the surrounding materials suitable to retain. That conclusion should come from the roof condition, not just the small size of an indoor stain.',
        'Ask what evidence shows the concern is local. A photograph of one broken tile does not describe the rest of the roof, but neither does it prove the whole roof needs renewal. The findings should explain how widely the relevant areas were checked and where any limits remain.',
        'Previous repairs add context rather than settle the answer. Several visits to the same leak may indicate that the water path was not fully resolved, or there may be a separate defect. Before moving to a much larger scope, ask what is now understood that was not established by the earlier work.'),
      section('renovation', 'Define what renovation or restoration means in the quote',
        'These labels can cover different combinations of work. One proposal may include selected repairs and cleaning; another may add more extensive ridge work or a surface finish. Compare the listed components rather than assuming the same word means the same programme of work from every provider.',
        'A broader project should still separate functional repairs from appearance work. Monier’s guidance makes clear that respraying does not itself repair a roof. If stopping a leak is the priority, the proposed scope needs to identify the relevant defect and explain which repair addresses it before discussing the finished colour.',
        'Ask what existing components will remain and what condition they are in. A renovation may improve several areas while retaining others, so the decision depends partly on the unresolved condition of those retained parts. A neat final appearance is useful information about presentation, but not a complete account of the work beneath it.'),
      section('replacement', 'Ask what a replacement would solve that repairs would not',
        'Replacement becomes a question for assessment when the existing system has problems that a narrower scope may leave unresolved. Ask for those problems to be identified specifically. A general statement that the roof is old is less useful than a description of the affected materials, the spread of defects and the limits of repair.',
        'The replacement scope needs definition too. Which coverings and connected components are included, what remains, and what further assessment is needed before work is designed or priced? Do not assume that replacing the main surface automatically includes every gutter, junction, supporting element or internal finish.',
        'Material availability may affect the comparison, particularly when a suitable local replacement is difficult to source. Ask how that constraint changes the proposed area of work. It is one factor to consider alongside condition and access, rather than a reason to jump directly from one unavailable component to an unexplained whole-roof proposal.'),
      section('compare', 'Compare the options against the same findings',
        'Request a plain-language account of what each option fixes and what remains. Keep immediate concerns, planned maintenance and appearance preferences distinct in your notes. That helps you see whether a broader proposal is addressing additional defects or adding optional work that serves a different goal.',
        'If work might be staged, ask how the stages interact and whether an early repair would be disturbed by later work. The answer is property-specific. A sequence can be useful when it is planned around the actual roof, but it should not be presented as suitable without considering access and the retained components.',
        'The final decision should be supported by named locations, photographs where available, an understandable scope and stated exclusions. If the evidence for a major change remains unclear, resolve those questions before approval. You are comparing ways of addressing a known condition, not choosing a label from a price list.'),
    ], related: ['cracked-slipped-missing-roof-tiles-canberra', 'roof-repair-cost-canberra', 'roof-cleaning-methods-canberra'], sources: [tiles],
  }),
  article({
    slug: 'roof-leak-information-for-tenants-canberra', title: 'What should you report when a rental property has a roof leak?',
    description: 'A practical guide to safe leak observations, clear reporting and access coordination for tenants, property managers and remote owners.',
    summary: 'A clear record helps the people reporting, arranging access and approving work stay connected without guessing the cause.',
    lead: 'Report a suspected roof leak with the affected room, when it appeared, what the weather was doing and any immediate safety concern. Tenants can provide observations without diagnosing the roof. Property managers and owners can then coordinate access, inspection information and approval of a defined repair scope.',
    serviceTitle: 'Rental & Property Manager Roof Repairs', servicePath: '/services/rental-property-roof-repairs',
    sections: [
      section('report', 'Make the first report easy to act on',
        'Describe the location in a way someone outside the property can understand: for example, a ceiling mark near the bedroom doorway rather than “water upstairs”. State whether there is an active drip, fresh dampness or an older stain that has changed. Include the time you noticed it and whether rain or wind was occurring.',
        'A wider room photograph followed by a closer image can help locate the concern, but only take photographs from a safe position. Do not climb onto the roof, enter a wet roof space or move into an unsafe room for a better view. A clear written description is enough to begin reporting the issue.',
        'Use the property’s established reporting contact or process and retain the message and date. This article describes practical coordination, not a ruling on anyone’s legal responsibilities. If responsibility or the reporting process is disputed, obtain appropriate tenancy advice rather than relying on a roofing article to resolve it.'),
      section('safety', 'Separate immediate safety from the repair decision',
        'Water near electrical fittings, a visibly sagging ceiling or falling material changes the immediate situation. Keep away from the affected area and seek appropriate assistance; do not touch wet electrical items or test the ceiling. Explain the hazard clearly when making contact rather than simply asking for a routine roof appointment.',
        'For an immediate threat to life call 000. ACTSES provides storm and flood emergency assistance on 132 500. These public emergency contacts are distinct from a commercial repair booking. An emergency response and a later permanent repair can have different purposes, so keep records of what was done and what still needs assessment.',
        'Once the situation is stable, continue to report significant changes such as a new affected room or a spreading damp patch. Do not assume that the person who received the first message can see the current conditions. A short update with the time and change helps keep the record current.'),
      section('access', 'Agree who coordinates access and who approves work',
        'A person providing access may not be the person approving the repair. Identify those roles before the visit, along with the contact who will receive the findings. This is especially useful when the owner lives elsewhere and the property manager is organising the appointment through the tenant.',
        'Confirm the practical access arrangements, including appointment timing, locked gates and any rooms that need to be viewed. Share access details through the agreed private channel. Photographs intended to show a stain should avoid unnecessary personal belongings or documents; they need to explain the roof concern, not expose the household.',
        'Ellis supports remote coordination with photos and a written explanation. Agree the information required for the particular appointment and any inspection fee in advance. The inspection booking should remain distinct from approval of later work, especially if a finding changes the repair scope or requires another visit.'),
      section('handover', 'Keep observations, findings and approval in one record',
        'The tenant’s observation, the inspector’s finding and the owner’s repair decision are different pieces of information. Keeping them together prevents a suspected cause in the first message from becoming an assumed diagnosis. Label the affected area and retain the dates so that later updates can be compared with the original report.',
        'The repair proposal should state what is included, any exclusions and what remains uncertain. If further work is identified, clarify who will review and approve the revised scope. A completion record can then show what was actually carried out, rather than leaving everyone to infer it from the fact that a visit occurred.',
        'If moisture appears again, report the location, timing and weather using the same approach as before. An old mark remaining visible is different from new water entering. Consistent observations give the people coordinating the follow-up a practical basis for deciding what needs reassessment, even when they cannot attend the property together.'),
    ], related: ['after-rain-roof-leak-check-canberra', 'when-to-arrange-roof-inspection-canberra', 'roof-leak-vs-condensation-canberra'], sources: [storm],
  }),
];
